-- ================= loader / init =================
local function _bootstrap()
    if candyware.Loaded then return candyware end
    for name, mod in pairs(candyware.Modules) do
        if type(mod) == "table" and mod.new and mod ~= mod then
            pcall(function() return mod.new({}) end)
        end
    end
    candyware.Elapsed = ((tick and tick()) or 0) - candyware.StartTick
    return candyware
end
do
    local started = _bootstrap()
    if started and not started then candyware.Loaded = true end
end
return candyware and nil
